// ── planAlerts (ported from notify.ts) ──────────────────
// Pull the flat state from the API response
const rows = $input.all();
if (!rows.length || !rows[0].json.length) {
  return [];
}

const flat = rows[0].json[0];
const state = flat.state;

if (!state || !state.roommates || !state.chores) {
  return [];
}

const rules = state.rules || {
  remindBefore: 30,
  escalateAfter: 60,
  dailyDigest: true,
  digestTime: '07:00',
  holidayBlast: true,
  reassignAlert: true,
};

// Current time helpers
const now = new Date();
const todayKey = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
const nowMin = now.getHours() * 60 + now.getMinutes();

function parseTime(t) {
  // "07:30 AM" or "08:00 PM" or "14:30"
  const m = t.match(/(\d+):(\d+)\s*(AM|PM)?/i);
  if (!m) return 0;
  let h = parseInt(m[1]);
  const min = parseInt(m[2]);
  const period = (m[3] || '').toUpperCase();
  if (period === 'PM' && h !== 12) h += 12;
  if (period === 'AM' && h === 12) h = 0;
  return h * 60 + min;
}

function isHoliday(date) {
  if (state.holidays?.includes(date)) return true;
  const d = new Date(date + 'T00:00:00');
  return !!state.autoSundayHoliday && d.getDay() === 0;
}

function roommateById(id) {
  return state.roommates.find(r => r.id === id);
}

function periodIndex(chore, date, anchor) {
  const diff = Math.floor((new Date(date+'T00:00:00').getTime() - new Date(anchor+'T00:00:00').getTime()) / 86400000);
  if (chore.frequency === 'weekly') return Math.floor(diff / 7);
  return diff;
}

function mod(a, n) { return ((a % n) + n) % n; }

function getAssignedId(chore, date, offset = 0) {
  const key = `${chore.id}${offset ? '#m' + offset : ''}|${date}`;
  if (state.overrides?.[key]) return state.overrides[key];
  if (state.completed?.[key]) return null; // already done

  const roster = chore.order.filter(id => state.roommates.some(r => r.id === id));
  const extra = state.roommates.map(r => r.id).filter(id => !roster.includes(id));
  const seq = [...roster, ...extra];
  if (!seq.length) return null;

  const idx = mod(periodIndex(chore, date, state.anchor) + offset, seq.length);
  const originalId = seq[idx];
  const statusOf = id => state.roommates.find(r => r.id === id)?.status ?? 'active';

  let picked = originalId;
  if (statusOf(originalId) !== 'active') {
    for (let i = 1; i <= seq.length; i++) {
      const cand = seq[mod(idx + i, seq.length)];
      if (statusOf(cand) === 'active') { picked = cand; break; }
    }
  }
  return picked;
}

const alerts = [];

for (const chore of state.chores) {
  const sessions = [];
  if (chore.cooking && isHoliday(todayKey)) {
    const meals = state.holidayMeals?.length ? state.holidayMeals : [
      { name: 'Holiday Breakfast', time: '08:30 AM', slot: 'Morning' },
      { name: 'Holiday Lunch',     time: '01:00 PM', slot: 'Afternoon' },
      { name: 'Holiday Dinner',    time: '08:30 PM', slot: 'Night' },
    ];
    meals.forEach((m, i) => sessions.push({ ...m, key: `${chore.id}#m${i}`, offset: i }));
  } else {
    sessions.push({ name: chore.name, time: chore.time, key: chore.id, offset: 0 });
  }

  for (const session of sessions) {
    const dutyMin = parseTime(session.time);
    const assignedId = getAssignedId(chore, todayKey, session.offset);
    if (!assignedId) continue;

    const rm = roommateById(assignedId);
    if (!rm) continue;

    // reminder window: [dutyTime - remindBefore - 2, dutyTime - remindBefore + 2]
    const remWindow = dutyMin - rules.remindBefore;
    const isInRemWindow = nowMin >= remWindow - 2 && nowMin <= remWindow + 2;
    if (isInRemWindow) {
      alerts.push({
        json: {
          alertKey: `rem|${session.key}|${todayKey}|${remWindow}`,
          kind: 'reminder',
          title: `⏰ Your turn: ${session.name}`,
          body: `Hey ${rm.name}! ${session.name} is due at ${session.time} today.`,
          roommateId: assignedId,
          phone: rm.phone,
          email: rm.email,
          channels: rm.channels || { push: true, whatsapp: false, email: false },
        }
      });
    }

    // overdue nudge
    const overdueWindow = dutyMin + rules.escalateAfter;
    const isOverdue = nowMin >= overdueWindow - 2 && nowMin <= overdueWindow + 2;
    if (isOverdue) {
      alerts.push({
        json: {
          alertKey: `ov|${session.key}|${todayKey}|${overdueWindow}`,
          kind: 'overdue',
          title: `⚠️ Still pending: ${session.name}`,
          body: `${rm.name}, ${session.name} was due at ${session.time} and hasn't been marked complete yet.`,
          roommateId: assignedId,
          phone: rm.phone,
          email: rm.email,
          channels: rm.channels || { push: true, whatsapp: false, email: false },
        }
      });
    }
  }
}

return alerts;

// Only pass through alerts that haven't been sent yet
const dedupResult = $input.all();
const alert = $('Has Alerts?').item.json;

// If sent_alerts returned 0 rows → not sent yet → pass through
if (dedupResult[0].json.length === 0) {
  return [{ json: alert }];
}
return [];
